14	// doRequest issues a request, optionally carrying tenant header lines.
15	func doRequest(t *testing.T, h http.Handler, method, target, body, contentType string, tenants ...string) *httptest.ResponseRecorder {
16		t.Helper()
17		var reader *strings.Reader
18		if body != "" {
19			reader = strings.NewReader(body)
20		} else {
21			reader = strings.NewReader("")
22		}
23		rec := httptest.NewRecorder()
24		req := httptest.NewRequest(method, target, reader)
25		if contentType != "" {
26			req.Header.Set("Content-Type", contentType)
27		}
28		for i, tv := range tenants {
29			if i == 0 {
30				req.Header.Set(tenantHeader, tv)
31			} else {
32				req.Header.Add(tenantHeader, tv)
33			}
34		}
35		h.ServeHTTP(rec, req)
36		return rec
